CREATE TABLE t0(id INTEGER PRIMARY KEY, c0 INT CHECK(c0 IS NULL OR length(c0) < 40), c1  DEFAULT 'd', c2 NUMERIC COLLATE NOCASE);
INSERT OR IGNORE INTO t0(c0, c1, c2) VALUES(206, NULL, x'');
INSERT OR IGNORE INTO t0(c0, c1, c2) VALUES('phi', NULL, -449.2);
INSERT OR IGNORE INTO t0(c0, c1, c2) VALUES('theta', x'6b673c2e', 'café');
INSERT OR IGNORE INTO t0(c0, c1, c2) VALUES('eta', NULL, -204);
CREATE TABLE t1(id INTEGER PRIMARY KEY, c0 INTEGER, c1 VARCHAR(10), c2, c3 TEXT COLLATE NOCASE, ref INTEGER REFERENCES t0(id));
INSERT OR IGNORE INTO t1(c0, c1, c2, c3, ref) VALUES('kappa', -347, NULL, NULL, 6);
INSERT OR IGNORE INTO t1(c0, c1, c2, c3, ref) VALUES(0.1, 9223372036854775807, x'68ac32693b09', x'1eebec', 8);
SELECT length('42'), upper('42'), lower('42'), substr('42', -2, 0), instr('42', 'eta'), replace('42', 'e', 'XY'), trim('42'), ltrim('42', 'ab'), hex('42'), quote('42'), unicode('42'), '42' LIKE 'a%', '42' GLOB '?', char(76, 458), '42' || 'eta', '42' < 'eta', '42' = 'eta' COLLATE NOCASE;
SELECT length('x_y'), upper('x_y'), lower('x_y'), substr('x_y', 3, 4), instr('x_y', 'kappa'), replace('x_y', 'e', '_'), trim('x_y'), ltrim('x_y', 'ab'), hex('x_y'), quote('x_y'), unicode('x_y'), 'x_y' LIKE '%é%', 'x_y' GLOB '?', char(90, 498), 'x_y' || 'kappa', 'x_y' < 'kappa', 'x_y' = 'kappa' COLLATE NOCASE;
SELECT length('über'), upper('über'), lower('über'), substr('über', 2, 4), instr('über', 'nu'), replace('über', 'é', ''), trim('über'), ltrim('über', 'ab'), hex('über'), quote('über'), unicode('über'), 'über' LIKE 'a%', 'über' GLOB '?', char(66, 374), 'über' || 'nu', 'über' < 'nu', 'über' = 'nu' COLLATE NOCASE;
SELECT length('zeta'), upper('zeta'), lower('zeta'), substr('zeta', -2, 1), instr('zeta', 'pi'), replace('zeta', 'e', ''), trim('zeta'), ltrim('zeta', 'ab'), hex('zeta'), quote('zeta'), unicode('zeta'), 'zeta' LIKE 'A%', 'zeta' GLOB '*[a-m]*', char(71, 538), 'zeta' || 'pi', 'zeta' < 'pi', 'zeta' = 'pi' COLLATE NOCASE;
SELECT length('1e3'), upper('1e3'), lower('1e3'), substr('1e3', -3, 4), instr('1e3', 'phi'), replace('1e3', 'é', 'XY'), trim('1e3'), ltrim('1e3', 'ab'), hex('1e3'), quote('1e3'), unicode('1e3'), '1e3' LIKE '%a_', '1e3' GLOB '*[a-m]*', char(72, 766), '1e3' || 'phi', '1e3' < 'phi', '1e3' = 'phi' COLLATE NOCASE;
SELECT length('42'), upper('42'), lower('42'), substr('42', -2, 1), instr('42', 'café'), replace('42', '', '_'), trim('42'), ltrim('42', 'ab'), hex('42'), quote('42'), unicode('42'), '42' LIKE '%', '42' GLOB '*', char(74, 571), '42' || 'café', '42' < 'café', '42' = 'café' COLLATE NOCASE;
SELECT length('nu'), upper('nu'), lower('nu'), substr('nu', 2, 3), instr('nu', 'nu'), replace('nu', 'é', 'XY'), trim('nu'), ltrim('nu', 'ab'), hex('nu'), quote('nu'), unicode('nu'), 'nu' LIKE '_', 'nu' GLOB '*[a-m]*', char(71, 243), 'nu' || 'nu', 'nu' < 'nu', 'nu' = 'nu' COLLATE NOCASE;
SELECT id, (SELECT count(*) FROM t1 WHERE t1.id <= t1.id) FROM t1 ORDER BY c0, id;
SELECT id FROM t1 WHERE id IN (SELECT id FROM t1 WHERE nullif(-0.0, NULL BETWEEN c3 AND x'10cf47')) ORDER BY id;
SELECT id FROM t1 x WHERE EXISTS (SELECT 1 FROM t1 y WHERE y.id = x.id + 0) ORDER BY id;
SELECT c2 FROM t1 INTERSECT SELECT c1 FROM t1 ORDER BY 1 LIMIT 24 OFFSET 0;
